// Routes
app.get('/api/config', async (req, res) => {
  try {
    if (!prisma) return res.json(defaultData);
    const configRow = await prisma.systemConfig.findFirst();
    if (configRow) {
      res.json(JSON.parse(configRow.config));
    } else {
      res.json(defaultData);
    }
  } catch (error) {
    console.error('ERROR /api/config:', error);
    res.json(defaultData); // Fallback to default on error
  }
});

app.post('/api/config', async (req, res) => {
  try {
    const newConfig = req.body.config;
    if (!newConfig) return res.status(400).json({ error: 'Missing config' });
    
    const configRow = await prisma.systemConfig.findFirst();
    if (configRow) {
      await prisma.systemConfig.update({
        where: { id: configRow.id },
        data: { config: JSON.stringify(newConfig) }
      });
    } else {
      await prisma.systemConfig.create({
        data: { config: JSON.stringify(newConfig) }
      });
    }
    res.json({ message: 'Configuration saved successfully' });
  } catch (error) {
    console.error(error);
    res.status(500).json({ error: 'Internal server error', details: error.message });
  }
});

app.get('/api/students', async (req, res) => {
  try {
    const students = await prisma.student.findMany({
      include: { evaluations: true }
    });
    res.json(students);
  } catch (error) {
    res.status(500).json({ error: 'Internal server error', details: error.message });
  }
});

app.post('/api/students', async (req, res) => {
  try {
    const { name, gradeId } = req.body;
    if (!name) return res.status(400).json({ error: 'Missing student name' });
    const student = await prisma.student.create({ data: { name, gradeId: gradeId || null } });
    res.json(student);
  } catch (error) {
    res.status(500).json({ error: 'Internal server error', details: error.message });
  }
});

app.delete('/api/students/:id', async (req, res) => {
  try {
    const id = parseInt(req.params.id);
    await prisma.evaluation.deleteMany({ where: { studentId: id } });
    await prisma.student.delete({ where: { id } });
    res.json({ message: 'Student deleted successfully' });
  } catch (error) {
    res.status(500).json({ error: 'Internal server error', details: error.message });
  }
});

app.post('/api/evaluations', async (req, res) => {
  try {
    const { id, student_id, grade_id, subject_id, evaluation_type, evaluation_date, scores } = req.body;
    
    if (!student_id || !grade_id || !subject_id || !evaluation_type || !evaluation_date || !scores) {
      return res.status(400).json({ error: 'Missing required fields' });
    }

    let evaluation;
    if (id) {
      evaluation = await prisma.evaluation.update({
        where: { id: parseInt(id) },
        data: {
          studentId: parseInt(student_id),
          gradeId: grade_id,
          subjectId: subject_id,
          evaluationType: evaluation_type,
          evaluationDate: evaluation_date,
          scores: JSON.stringify(scores)
        }
      });
    } else {
      evaluation = await prisma.evaluation.create({
        data: {
          studentId: parseInt(student_id),
          gradeId: grade_id,
          subjectId: subject_id,
          evaluationType: evaluation_type,
          evaluationDate: evaluation_date,
          scores: JSON.stringify(scores)
        }
      });
    }
    
    res.json({ message: 'تم حفظ التقييم بنجاح', evaluation });
  } catch (error) {
    console.error(error);
    res.status(500).json({ error: 'Internal server error', details: error.message });
  }
});

app.get('/api/evaluations', async (req, res) => {
  try {
    const { student_id, grade_id, subject_id, evaluation_type } = req.query;
    
    if (!student_id || student_id === 'undefined' || !grade_id || !subject_id || !evaluation_type) {
      return res.json([]); // Return empty instead of 500
    }

    const evaluations = await prisma.evaluation.findMany({
      where: {
        studentId: parseInt(student_id),
        gradeId: grade_id,
        subjectId: subject_id,
        evaluationType: evaluation_type
      },
      orderBy: {
        id: 'desc'
      }
    });
    
    const parsedEvaluations = evaluations.map(e => ({
      ...e,
      scores: typeof e.scores === 'string' ? JSON.parse(e.scores) : e.scores
    }));
    
    res.json(parsedEvaluations);
  } catch (error) {
    console.error(error);
    res.status(500).json({ error: 'Internal server error', details: error.message });
  }
});

app.get('/api/evaluations/batch', async (req, res) => {
  try {
    const { evaluation_ids, student_ids, grade_id, subject_id, evaluation_type, mode, eval_label } = req.query;

    // Case 1: Specific evaluation IDs requested
    if (evaluation_ids) {
      const eids = String(evaluation_ids).split(',').map(id => parseInt(id.trim())).filter(Boolean);
      const evals = await prisma.evaluation.findMany({
        where: { id: { in: eids } },
        orderBy: { id: 'asc' }
      });
      const results = await Promise.all(evals.map(async (ev) => {
        const student = await prisma.student.findUnique({ where: { id: ev.studentId } });
        if (!student) return null;
        let parsedScores = {};
        if (ev.scores) {
          try {
            parsedScores = typeof ev.scores === 'string' ? JSON.parse(ev.scores) : ev.scores;
          } catch (e) {
            console.error('Error parsing scores:', e);
          }
        }
        return { student, evaluation: { ...ev, scores: parsedScores } };
      }));
      return res.json(results.filter(Boolean));
    }

    // Case 2: By student IDs or all students of a grade
    if (!grade_id || !subject_id || !evaluation_type) {
      return res.status(400).json({ error: 'Missing required query parameters: grade_id, subject_id, evaluation_type' });
    }

    let ids = [];
    if (student_ids && student_ids !== 'all') {
      ids = String(student_ids).split(',').map(id => parseInt(id.trim())).filter(Boolean);
    } else {
      const allStudents = await prisma.student.findMany({
        where: {
          OR: [
            { gradeId: grade_id },
            { gradeId: null },
            { gradeId: '' }
          ]
        },
        orderBy: { id: 'asc' }
      });
      ids = allStudents.map(s => s.id);
    }

    const flatResults = [];
    for (const sid of ids) {
      const student = await prisma.student.findUnique({ where: { id: sid } });
      if (!student) continue;

      const whereClause = {
        studentId: sid,
        gradeId: grade_id,
        subjectId: subject_id,
        evaluationType: evaluation_type
      };

      const evals = await prisma.evaluation.findMany({
        where: whereClause,
        orderBy: { id: 'asc' }
      });

      if (evals.length === 0) continue;

      let filteredEvals = evals;

      // Filter by eval_label if specified (e.g. "التقييم الأول")
      if (eval_label && eval_label !== 'all') {
        filteredEvals = evals.filter(ev => {
          let ps = {};
          try { ps = typeof ev.scores === 'string' ? JSON.parse(ev.scores) : (ev.scores || {}); } catch (e) {}
          return ps._evaluationLabel === eval_label;
        });
      } else if (mode === 'latest') {
        filteredEvals = [evals[evals.length - 1]];
      }

      for (const ev of filteredEvals) {
        let parsedScores = {};
        if (ev && ev.scores) {
          try {
            parsedScores = typeof ev.scores === 'string' ? JSON.parse(ev.scores) : ev.scores;
          } catch (e) {
            console.error(`Error parsing scores for student ${sid}:`, e);
          }
        }
        flatResults.push({ student, evaluation: { ...ev, scores: parsedScores } });
      }
    }

    res.json(flatResults);
  } catch (error) {
    console.error('Batch fetch error:', error);
    res.status(500).json({ error: 'Internal server error', details: error.message });
  }
});

app.get('*', (req, res) => {
  const indexPath = path.join(process.cwd(), 'dist', 'index.html');
  res.sendFile(indexPath, (err) => {
    if (err) {
      res.status(404).send('Frontend files not found.');
    }
  });
});

async function initializeConfig() {
  try {
    const configRow = await prisma.systemConfig.findFirst();
    if (!configRow) {
      await prisma.systemConfig.create({
        data: { config: JSON.stringify(defaultData) }
      });
      console.log('System configuration initialized with default data.');
    } else {
      await prisma.systemConfig.update({
        where: { id: configRow.id },
        data: { config: JSON.stringify(defaultData) }
      });
      console.log('System configuration FORCE UPDATED with new assessment criteria.');
    }
  } catch (error) {
    console.error('Failed to initialize configuration:', error);
  }
}

app.listen(port, () => {
  console.log(`Server is running on port ${port}`);
  initializeConfig();
});
